import re
ZH_REFUSAL_RE = re.compile(r"^(抱歉[，,]?\s*)?(我(不能|无法|只能|必须|是一个)|为了(安全|您的安全|确保安全)|对不起)")

def _bare_zh_refusal(r: str) -> bool:
    text = r.strip()
    if len(text) > 200:
        return False
    if not ZH_REFUSAL_RE.match(text):
        return False
    if any(s in text for s in ["**", "##", "1.", "•", "\n\n"]):
        return False
    return True

def _is_chinese_user_compliance(r: str) -> bool:
    if _bare_zh_refusal(r):
        return False
    return _is_chinese(r)
